/// <summary>
/// This is an extension class for PurchaseOrderConfirmedBusinessEvent.
/// </summary>
[ExtensionOf(classStr(PurchaseOrderConfirmedBusinessEvent))]
final class METPurchaseOrderConfirmedBusinessEvent_Extension
{
}

Method.Source:
    /// <summary>
    /// It returns PurchaseOrderConfirmedBusinessEventContract buffer.
    /// </summary>
    /// <returns>BusinessEventsContract.</returns>
    public BusinessEventsContract buildContract()
    {
        Var contract = PurchaseOrderConfirmedBusinessEventContract::construct();
        contract = next buildContract();

        PurchTable purchOrder = this.getContextRecord();

        METPurchTable metPurchTable = METPurchTable::find(purchOrder.PurchId);
        contract.parmPOChngSubMode(metPurchTable.POChngSubMode);
        contract.parmPOSubMode(metPurchTable.POSubMode);

        return contract;
    }
